INSERT INTO analysis_results (id, entity_id, run_id, kind, payload, computed_at) VALUES ('res_7774f604239a489abc8702','ent_germany','run_b14745c67f9a4d5090bc92','recommendations','[{"headline":"Germany has a broad export base","detail":"No single product dominates. The largest is medicaments; consisting of mixed or unmixed products n.e.c. in heading no. 3004, for therapeutic or prophylactic uses, packaged for retail sale at 6%. Diversified exporters are more resilient and usually have the customs, logistics and finance capacity to handle varied goods.","angle":"entry","strength":"moderate","evidence":["Export concentration (HHI) 0.08"]},{"headline":"Growing demand for electric accumulators; lithium-ion, including separators, whether or not rectangular (including square), blood, human or animal, antisera, other blood fractions and immunological products; immunological products, put up in measured doses or in forms or packings for retail sale, vehicles; with both spark-ignition internal combustion reciprocating piston engine and electric motor for propulsion, capable of being charged by plugging to external source of electric power","detail":"These are the fastest-growing things Germany buys from abroad. Rising imports mean domestic demand is outpacing domestic supply. That gap is either a place to sell into, or a place to produce locally and displace the import.","angle":"gap","strength":"strong","evidence":["Electric accumulators; lithium-ion, including separators, whether or not rectangular (including square): $28.8bn, growing 20%/yr","Blood, human or animal, antisera, other blood fractions and immunological products; immunological products, put up in measured doses or in forms or packings for retail sale: $18.5bn, growing 11%/yr","Vehicles; with both spark-ignition internal combustion reciprocating piston engine and electric motor for propulsion, capable of being charged by plugging to external source of electric power: $13.6bn, growing 19%/yr"]},{"headline":"United States, France, Netherlands take 25% of exports","detail":"Export destinations are reasonably spread, which means established routes and documentation for several markets rather than just one.","angle":"partner","strength":"moderate","evidence":["United States: 10.0% ($166.3bn)","France: 8.0% ($132.7bn)","Netherlands: 7.6% ($126.2bn)"]},{"headline":"Most imports arrive from China","detail":"China supplies 14% of what Germany imports. If you are sourcing to sell here, that is your incumbent competition and the price you have to beat. If you are buying, those trade lanes already exist.","angle":"partner","strength":"moderate","evidence":["China: 14.0% ($200.4bn)","United States: 7.4% ($105.3bn)","Netherlands: 7.0% ($99.4bn)"]},{"headline":"2025 trade surplus of $224.2bn","detail":"Germany sells more than it buys. Surplus economies usually have foreign currency available, which makes getting paid and repatriating profit simpler.","angle":"risk","strength":"watch","evidence":["Exports $1773.8bn vs imports $1549.7bn in 2025","Exports moved 8.8% year on year"]},{"headline":"Services are a real part of this economy","detail":"Commercial services exports are $518.0bn, about 10% of GDP. That usually signals working payment rails, English or lingua-franca business capability, and buyers already used to contracting across borders.","angle":"entry","strength":"moderate","evidence":["Services exports $518.0bn against GDP $5050.9bn (2025)"]},{"headline":"Early signal: petroleum gases and other gaseous hydrocarbons; liquefied, natural gas","detail":"Not a headline product yet, but growing 163% a year. Categories that hold that rate tend to reprice the market before they show up in the top ten, which is the window where entry is cheapest.","angle":"timing","strength":"strong","evidence":["Minerals & energy: growing 163% a year since 2022, now 0.47% of imports at rank 40. Largest counterpart across all imports is China. Growth is uneven, so treat the projection as directional."]}