 treat the projection as directional."]}]','2026-09-06 01:48:54'),('res_235b13e5842447c4991646','ent_kenya','run_b14745c67f9a4d5090bc92','overview','{"year":2024,"export_usd":8255797029.967,"import_usd":20203122341.75,"balance_usd":-11947325311.783,"total_trade_usd":28458919371.717,"export_yoy_pct":15.334883083869725,"import_yoy_pct":8.592942519668537,"export_concentration":0.07977815465329365,"export_chapter_shares":{"10":0.0032139746874460767,"11":0.002737408505196235,"12":0.008695032576437306,"13":0.0018550928539560925,"14":0.0000048036835033683164,"15":0.03539750229908922,"16":0.0007747460339425421,"17":0.00788047445593219,"18":0.0005806612691179891,"19":0.004286092715284454,"20":0.015625545463845657,"21":0.018581063220573193,"22":0.006601109683316798,"23":0.007317660002871478,"24":0.011772937739048568,"25":0.02609469381878849,"26":0.01791683899678274,"27":0.12896100488840556,"28":0.011161386969247072,"29":0.0007865179809329119,"30":0.021137861735287828,"31":0.006540099783222132,"32":0.004179933946625419,"33":0.006325222941947908,"34":0.019191559107124966,"35":0.0014702874627298662,"36":0.0018359948435001999,"37":0.00003384734108478739,"38":0.007188269649508523,"39":0.01896251067725968,"40":0.0006004217344501524,"41":0.0023619703631549524,"42":0.0002868751667953786,"43":0.000011481714685565845,"44":0.0018513473069316484,"45":2.5800052887310758e-11,"46":0.000206976323521273,"47":0.00018132886365380363,"48":0.007614724517672224,"49":0.002707238569683533,"50":2.935339848114307e-7,"51":0.00021443412932445916,"52":0.0003426907189858561,"53":0.006029801653470526,"54":0.00009117051003895517,"55":0.0010365876447711413,"56":0.0005861894735826031,"57":0.00003662022587312588,"58":0.000040255800232701345,"59":0.00004093206722179224,"60":0.00008541735297518451,"61":0.029024179188186255,"62":0.02201375422304569,"63":0.004306369115902397,"64":0.002086570207997596,"65":0.00015794997106482022,"66":0.00007587026979061471,"67":0.00243043460239781,"68":0.0004983075590482924,"69":0.