INSERT INTO analysis_results (id, entity_id, run_id, kind, payload, computed_at) VALUES ('res_3180133842f749e695971a','ent_china','run_b14745c67f9a4d5090bc92','recommendations','[{"headline":"China has a broad export base","detail":"No single product dominates. The largest is electronic integrated circuits; memories at 4%. Diversified exporters are more resilient and usually have the customs, logistics and finance capacity to handle varied goods.","angle":"entry","strength":"moderate","evidence":["Export concentration (HHI) 0.11"]},{"headline":"Growing demand for metals; gold, non-monetary, unwrought (but not powder), coal; bituminous, whether or not pulverised, but not agglomerated","detail":"These are the fastest-growing things China buys from abroad. Rising imports mean domestic demand is outpacing domestic supply. That gap is either a place to sell into, or a place to produce locally and displace the import.","angle":"gap","strength":"strong","evidence":["Metals; gold, non-monetary, unwrought (but not powder): $99.8bn, growing 29%/yr","Coal; bituminous, whether or not pulverised, but not agglomerated: $35.4bn, growing 21%/yr"]},{"headline":"United States, Hong Kong SAR, China, Viet Nam take 28% of exports","detail":"Export destinations are reasonably spread, which means established routes and documentation for several markets rather than just one.","angle":"partner","strength":"moderate","evidence":["United States: 14.9% ($525.6bn)","Hong Kong SAR, China: 8.3% ($290.9bn)","Viet Nam: 4.6% ($161.9bn)"]},{"headline":"Most imports arrive from Taiwan","detail":"Taiwan supplies 9% of what China imports. If you are sourcing to sell here, that is your incumbent competition and the price you have to beat. If you are buying, those trade lanes already exist.","angle":"partner","strength":"moderate","evidence":["Taiwan: 8.5% ($217.8bn)","Korea, Rep.: 7.1% ($181.5bn)","United States: 6.4% ($164.6bn)"]},{"headline":"2024 trade surplus of $991.4bn","detail":"China sells more than it buys. Surplus economies usually have foreign currency available, which makes getting paid and repatriating profit simpler.","angle":"risk","strength":"watch","evidence":["Exports $3576.5bn vs imports $2585.1bn in 2024","Exports moved 5.8% year on year"]},{"headline":"Early signal: vehicles; with only spark-ignition internal combustion reciprocating piston engine, cylinder capacity over 1500 but not over 3000cc","detail":"Not a headline product yet, but growing 66% a year. Categories that hold that rate tend to reprice the market before they show up in the top ten, which is the window where entry is cheapest.","angle":"timing","strength":"strong","evidence":["Transport equipment: growing 66% a year since 2021, now 1.12% of exports at rank 12. Largest counterpart across all exports is United States. Growth is uneven, so treat the projection as directional."]}]','2026-09-06 01:33:19'),('res_990abf633aba45e483dd00','ent_ghana','run_3ea16bccb13e4e83ae1fb0','overview','{"year":2025,"export_usd":31975161923.111,"import_usd":20166910856.186,"balance_usd":11808251066.925,"total_trade_usd":52142072779.297,"export_yoy_pct":54.88891413911926,"import_yoy_pct":15.043655830193128,"export_concentration":0.42697516400772556,"export_chapter_shares":{"10":0.00014382806016929905,"11":0.00019404926473619253,"12":0.0064258675048180025,"13":0.000010274195945903051,"14":0.000017731476711936317,"15":0.008181283044666579,"16":0.005976271023819097,"17":0.0002452615604530294,"18":0.13989677275983162,"19":0.001941665479264706,"20":0.0017800522276281198,"21":0.001914861737095676,"22":0.0034082972850635568,"23":0.0005714749678810474,"24":0.0000016225157240722305,"25":0.0007275951746216492,"26":0.011898338888537148,"27":0.08797173341002104,"28":0.0010733165238546217,"29":0.00011103324184995397,"30":0.0005709325871718673,"31":0.0018007381735379658,"32":0.0014258419529394229,"33":0.00121334793741766,"34":0.00143415994659461,"35":0.00006995594147041327,"36":0.0005185642144009442,"37":0.0000024